  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  if (product) {
    console.log('\nProduct ' + pid + ':', JSON.stringify(product, null, 2));
  } else {
    console.log('\nProduct ' + pid + ': NOT FOUND');
  }
}
