node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update CI-0006 quantity from 3 to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006'\").run();

// Recalculate cart totals
// CI-0005: 1 × 49 = 49
// CI-0006: 2 × 89 = 178
// CI-0007: 2 × 72 = 144
// New subtotal: 371
const newSubtotal = 49 + (2 * 89) + (2 * 72);
console.log('New subtotal:', newSubtotal);

// Update cart: subtotal and total (shipping is 0, no discounts)
db.prepare(\"UPDATE carts SET subtotal = ?, total = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(newSubtotal, newSubtotal);

// Verify the changes
const item = db.prepare(\"SELECT * FROM cart_items WHERE cart_item_id = 'CI-0006'\").get();
console.log('Updated item:', JSON.stringify(item, null, 2));

const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log('Updated cart:', JSON.stringify(cart, null, 2));
"

